export default function config({ owner, project, path, branch }) {
  for (const [k, v] of Object.entries({ owner, project, path, branch }))
    if (typeof v !== "string" || !v.trim() || v.includes("YOUR_")) throw Error("Configure " + k);
  if (
    owner.split("/").some((x) => !x || x === "." || x === "..") ||
    project.includes("/") ||
    path.startsWith("/") ||
    path.split("/").some((x) => x === "." || x === "..")
  )
    throw Error("Invalid repository configuration");
  const endpoint = "/projects/" + encodeURIComponent(owner + "/" + project);
  return {
    owner,
    project,
    path: path.replace(/\/+$/, ""),
    branch,
    projectEndpoint: endpoint,
    branchEndpoint: endpoint + "/repository/branches/" + encodeURIComponent(branch),
  };
}

