export default function next({ state, previous }) {
  const index = previous?.index ?? 0,
    items = state?.items;
  if (!Array.isArray(items)) throw Error("Missing workflow list");
  if (index >= items.length) return { state: { index }, more: false, id: "", name: "" };
  const x = items[index];
  if (typeof x?.id !== "string" || !x.id || typeof x?.name !== "string" || !x.name)
    throw Error("Invalid workflow");
  return { state: { index: index + 1 }, more: true, id: x.id, name: x.name };
}

