export default async function workflow({ id }, context) {
  const w = await context.actions.call("n8n.get_workflow", { workflowId: id });
  if (
    !w ||
    w.id !== id ||
    typeof w.name !== "string" ||
    !Array.isArray(w.nodes) ||
    typeof w.connections !== "object" ||
    !w.connections
  )
    throw Error("Invalid n8n workflow");
  return { workflow: w };
}

