export default function item({ id, workflow, path, projectEndpoint, branch }) {
  if (!/^[A-Za-z0-9_-]+$/.test(id) || workflow?.id !== id) throw Error("Workflow ID mismatch");
  const filePath = (path ? path + "/" : "") + id + ".json",
    endpoint = projectEndpoint + "/repository/files/" + encodeURIComponent(filePath);
  return {
    item: { workflow, filePath, endpoint, branch, content: JSON.stringify(workflow, null, 4) },
    endpoint: endpoint + "?ref=" + encodeURIComponent(branch),
  };
}

