export default async function check({ item, acknowledge, resolution }, ctx) {
  const key = "gitlab-backup:" + item.endpoint + ":" + item.branch,
    old = await ctx.state.get(key);
  if (old?.status === "pending") {
    if (acknowledge !== key || !["absent", "confirmed"].includes(resolution))
      throw Error("Inspect pending GitLab write " + key);
    await ctx.state.set(key, { status: "done" });
  }
  return { ok: true };
}

