import { Buffer } from "node:buffer";
export default function compare({ body, statusCode, bodyEncoding, item }) {
  let exists = false,
    changed = true,
    lastCommit = "";
  if (statusCode === 200) {
    if (
      bodyEncoding ||
      body?.file_path !== item.filePath ||
      body.encoding !== "base64" ||
      typeof body.content !== "string" ||
      !body.last_commit_id
    )
      throw Error("Invalid GitLab file");
    let old = JSON.parse(Buffer.from(body.content.replace(/\s/g, ""), "base64").toString("utf8"));
    const clean = (x) =>
      Array.isArray(x)
        ? x.map(clean)
        : x && typeof x === "object"
          ? Object.fromEntries(
              Object.keys(x)
                .filter((k) => k !== "updatedAt" && k !== "global")
                .sort()
                .map((k) => [k, clean(x[k])]),
            )
          : x;
    exists = true;
    changed = JSON.stringify(clean(old)) !== JSON.stringify(clean(item.workflow));
    lastCommit = body.last_commit_id;
  } else if (statusCode !== 404) throw Error("GitLab file read failed");
  const common = {
    branch: item.branch,
    content: item.content,
    commit_message: "Back up workflow " + item.workflow.name,
  };
  return {
    exists,
    changed,
    endpoint: item.endpoint,
    createBody: common,
    updateBody: { ...common, last_commit_id: lastCommit },
  };
}

