export default async function confirm({ body, statusCode, bodyEncoding, item, key }, ctx) {
  if (
    statusCode < 200 ||
    statusCode >= 300 ||
    bodyEncoding ||
    body?.file_path !== item.filePath ||
    body?.branch !== item.branch
  )
    throw Error("Unknown GitLab write");
  await ctx.state.set(key, { status: "done" });
  return { ok: true };
}

